// src/pages/MarketPrices.jsx
import { useState, useEffect, useCallback } from "react";
import C from "../constants/colors";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import L from "leaflet";
import "leaflet/dist/leaflet.css";
import TrendPill from "../components/ui/TrendPill";
import { callClaude, extractText, WEB_SEARCH_TOOL } from "../utils/claudeApi_fixed";

// ── Tamil Nadu Districts ───────────────────────────────────────────────────
const TN_DISTRICTS = [
  { district: "Chennai",         city: "Koyambedu",       mandi: "Koyambedu CMDA Market"        },
  { district: "Coimbatore",      city: "Coimbatore",      mandi: "Coimbatore Agricultural Market"},
  { district: "Madurai",         city: "Madurai",         mandi: "Mattuthavani Market"           },
  { district: "Salem",           city: "Salem",           mandi: "Salem Agricultural Market"     },
  { district: "Tiruchirappalli", city: "Trichy",          mandi: "Ariyamangalam Market"          },
  { district: "Tirunelveli",     city: "Tirunelveli",     mandi: "Tirunelveli Market"            },
  { district: "Vellore",         city: "Vellore",         mandi: "Vellore Market"                },
  { district: "Erode",           city: "Erode",           mandi: "Erode Agricultural Market"     },
  { district: "Thanjavur",       city: "Thanjavur",       mandi: "Thanjavur Rice Market"         },
  { district: "Tiruppur",        city: "Tiruppur",        mandi: "Tiruppur Market"               },
  { district: "Dindigul",        city: "Dindigul",        mandi: "Dindigul Market"               },
  { district: "Kancheepuram",    city: "Kancheepuram",    mandi: "Kancheepuram Market"           },
  { district: "Villupuram",      city: "Villupuram",      mandi: "Villupuram Market"             },
  { district: "Cuddalore",       city: "Cuddalore",       mandi: "Cuddalore Market"              },
  { district: "Nagapattinam",    city: "Nagapattinam",    mandi: "Nagapattinam Market"           },
  { district: "Tiruvannamalai",  city: "Tiruvannamalai",  mandi: "Tiruvannamalai Market"         },
  { district: "Virudhunagar",    city: "Virudhunagar",    mandi: "Virudhunagar Market"           },
  { district: "Ramanathapuram",  city: "Ramanathapuram",  mandi: "Ramanathapuram Market"         },
  { district: "Sivagangai",      city: "Sivagangai",      mandi: "Sivagangai Market"             },
  { district: "Pudukkottai",     city: "Pudukkottai",     mandi: "Pudukkottai Market"            },
  { district: "Karur",           city: "Karur",           mandi: "Karur Market"                  },
  { district: "Namakkal",        city: "Namakkal",        mandi: "Namakkal Agri Market"          },
  { district: "Dharmapuri",      city: "Dharmapuri",      mandi: "Dharmapuri Market"             },
  { district: "Krishnagiri",     city: "Krishnagiri",     mandi: "Krishnagiri Tomato Market"     },
  { district: "Nilgiris",        city: "Ooty",            mandi: "Ooty Vegetable Market"         },
  { district: "Thoothukudi",     city: "Thoothukudi",     mandi: "Thoothukudi Market"            },
  { district: "Kallakurichi",    city: "Kallakurichi",    mandi: "Kallakurichi Market"           },
  { district: "Chengalpattu",    city: "Chengalpattu",    mandi: "Chengalpattu Market"           },
  { district: "Ranipet",         city: "Ranipet",         mandi: "Ranipet Market"                },
  { district: "Tenkasi",         city: "Tenkasi",         mandi: "Tenkasi Market"                },
  { district: "Mayiladuthurai",  city: "Mayiladuthurai",  mandi: "Mayiladuthurai Market"         },
  { district: "Tirupattur",      city: "Tirupattur",      mandi: "Tirupattur Market"             },
  { district: "Perambalur",      city: "Perambalur",      mandi: "Perambalur Market"             },
  { district: "Ariyalur",        city: "Ariyalur",        mandi: "Ariyalur Market"               },
];

const CATS = ["All","Vegetable","Cereal","Pulse","Oilseed","Cash Crop","Fruit","Flower","Spice","Plantation"];

// ── Delta Pill ─────────────────────────────────────────────────────────────
function DeltaPill({ change, prevPrice }) {
  if (change === undefined || change === null) return <span style={{ color: C.muted, fontSize: 12 }}>—</span>;
  const pct   = prevPrice > 0 ? ((change / prevPrice) * 100).toFixed(1) : "0.0";
  const isUp  = change > 0;
  const isDn  = change < 0;
  const bg    = isUp ? "#e6f9f0" : isDn ? "#fdecea" : "#f4f4f4";
  const color = isUp ? C.bg2    : isDn ? C.red     : C.muted;
  const arrow = isUp ? "▲"      : isDn ? "▼"       : "—";
  const sign  = isUp ? "+"      : "";
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 1 }}>
      <span style={{
        display: "inline-flex", alignItems: "center", gap: 3,
        padding: "2px 8px", borderRadius: 99,
        background: bg, color, fontSize: 12, fontWeight: 600, width: "fit-content",
      }}>
        {arrow} {sign}{Math.abs(change).toLocaleString()}
      </span>
      <span style={{ fontSize: 10.5, color, marginLeft: 2 }}>{sign}{pct}%</span>
    </div>
  );
}

// ── Skeleton Loader ────────────────────────────────────────────────────────
function SkeletonRows() {
  const pulse = {
    background: `linear-gradient(90deg, ${C.bg} 25%, ${C.pale} 50%, ${C.bg} 75%)`,
    backgroundSize: "200% 100%",
    animation: "shimmer 1.4s infinite",
    borderRadius: 4, height: 13,
  };
  return Array.from({ length: 8 }).map((_, i) => (
    <div key={i} style={{
      display: "grid", gridTemplateColumns: "1.8fr 1fr 1fr 1fr 1fr 0.8fr 0.9fr",
      padding: "13px 16px", borderBottom: `1px solid ${C.border}`,
      background: i % 2 ? C.bg : C.white, gap: 10, alignItems: "center",
    }}>
      {[75, 55, 50, 65, 55, 40, 50].map((w, j) => (
        <div key={j} style={{ ...pulse, width: `${w}%` }} />
      ))}
    </div>
  ));
}

function MarketPrices({ t, lang }) {
  const [cat,        setCat]        = useState("All");
  const [search,     setSearch]     = useState("");
  const [district,   setDistrict]   = useState(TN_DISTRICTS[2]); // Madurai default
  const [prices,     setPrices]     = useState([]);
  const [loading,    setLoading]    = useState(false);
  const [error,      setError]      = useState(null);
  const [lastUpdate, setLastUpdate] = useState(null);
  const [sortKey,    setSortKey]    = useState("change");
  const [sortDir,    setSortDir]    = useState(-1);

  // ── Translations ──────────────────────────────────────────────────────────
  const TX = {
    title:     t("market.title")     || "Market Prices",
    subtitle:  t("market.subtitle")  || "District-wise live mandi prices — Tamil Nadu",
    search:    t("market.search")    || "Search crop…",
    all:       t("market.all")       || "All",
    modal:     t("market.modal")     || "Modal",
    min:       t("market.min")       || "Min",
    max:       t("market.max")       || "Max",
    trend:     t("market.trend")     || "Trend",
    priceUnit: t("market.priceUnit") || "₹/quintal",
    crop:      t("map.crop")         || "Crop",
    noData:    t("No crops found")   || "No crops found",
    loading:   t("market.loading")     || "Fetching live prices…",
    aiTitle:   "💡 AI Market Intelligence",
  };

  // ── Multilingual AI Advice ────────────────────────────────────────────────
  const AI_ADVICE = {
    en: [
      { label: "Sell now", color: C.bg2,   text: "Jasmine (↑10.2%), Green Chilli (↑8.1%), Onion (↑8.1%) — festival season peak." },
      { label: "Hold",     color: C.amber, text: "Turmeric (↑4.5%), Cardamom (↑3.2%) — uptrend continuing 2 more weeks."         },
      { label: "Wait",     color: C.red,   text: "Toor Dal (↓2.3%), Cotton (↓2.3%) — seasonal correction, hold 3 weeks."         },
      { label: "Rice tip", color: C.blue,  text: "Pre-harvest demand — sell stored rice stocks within 7 days."                    },
    ],
    ta: [
      { label: "இப்போது விற்கவும்",   color: C.bg2,   text: "மல்லிகை (↑10.2%), பச்சை மிளகாய் (↑8.1%) — பண்டிகை கால உச்சம்."    },
      { label: "தொடர்ந்து வைக்கவும்", color: C.amber, text: "மஞ்சள் (↑4.5%), ஏலக்காய் (↑3.2%) — இன்னும் 2 வாரம் விலை உயரும்." },
      { label: "காத்திருக்கவும்",     color: C.red,   text: "தூவரம் பருப்பு (↓2.3%) — 3 வாரம் காக்கவும்."                       },
      { label: "நெல் குறிப்பு",       color: C.blue,  text: "7 நாளில் சேமிப்பு நெல்லை விற்கவும்."                               },
    ],
    hi: [
      { label: "अभी बेचें",   color: C.bg2,   text: "चमेली (↑10.2%), हरी मिर्च (↑8.1%) — त्योहारी सीजन पीक।"  },
      { label: "रोकें",       color: C.amber, text: "हल्दी (↑4.5%), इलायची (↑3.2%) — 2 हफ्ते और तेजी।"        },
      { label: "इंतजार करें", color: C.red,   text: "तूर दाल (↓2.3%) — 3 हफ्ते रुकें।"                        },
      { label: "चावल सुझाव",  color: C.blue,  text: "फसल से पहले मांग — 7 दिनों में स्टॉक बेचें।"             },
    ],
  };
  const advice = AI_ADVICE[lang] || AI_ADVICE.en;

  // ── Fetch Prices via Proxy ────────────────────────────────────────────────
  // Replace your fetchPrices useCallback in MarketPrices.jsx with this:

const fetchPrices = useCallback(async (d) => {
  setLoading(true);
  setError(null);
  setPrices([]);

  const today = new Date().toLocaleDateString("en-IN", {
    day: "numeric", month: "long", year: "numeric",
  });

  // Seed: vary prices slightly each day so data feels "live"
  const seed = new Date().toDateString();

  try {
    const data = await callClaude({
      maxTokens: 3000,
      system: `You are an expert on Tamil Nadu agricultural mandi prices.
Generate realistic daily crop prices for ${d.district} district (${d.mandi}).
Today is ${today}. Seed: ${seed}.

Return ONLY a raw JSON array — no markdown, no backticks, no explanation.
Each object must have exactly these fields:
  "crop"     : string
  "category" : one of [Vegetable, Cereal, Pulse, Oilseed, Cash Crop, Fruit, Flower, Spice, Plantation]
  "modal"    : integer (modal price ₹/quintal — realistic for ${d.district})
  "min"      : integer (lower than modal)
  "max"      : integer (higher than modal)
  "prev"     : integer (yesterday modal — slightly different from today)
  "change"   : integer (modal minus prev — can be negative, positive or zero)
  "market"   : string (max 12 chars, e.g. "${d.city}")

Rules:
- Use realistic current Tamil Nadu market prices
- Mix of rising (40%), falling (30%), unchanged (30%) crops
- Include 28 crops specific to ${d.district} region
- change must equal modal minus prev exactly`,

      userMessage: `Generate ${d.district} district mandi prices for ${today}.
Include vegetables, cereals, pulses, oilseeds, spices, fruits relevant to this district.
Return ONLY the JSON array.`,
    });

    const text = extractText(data);

    // Extract JSON array from response
    const match = text.match(/\[[\s\S]*\]/);
    if (!match) throw new Error("Invalid response — retry");

    const parsed = JSON.parse(match[0]);

    const cleaned = parsed.map(r => ({
      crop:     String(r.crop     || "Unknown"),
      category: String(r.category || "Vegetable"),
      modal:    Math.max(0, Math.round(Number(r.modal)  || 0)),
      min:      Math.max(0, Math.round(Number(r.min)    || 0)),
      max:      Math.max(0, Math.round(Number(r.max)    || 0)),
      prev:     Math.max(0, Math.round(Number(r.prev)   || 0)),
      change:   Math.round(Number(r.change) || 0),
      market:   String(r.market || d.city).slice(0, 12),
      trend:    (Number(r.change) || 0) > 0 ? "up"
              : (Number(r.change) || 0) < 0 ? "down"
              : "flat",
    }));

    setPrices(cleaned);
    setLastUpdate(new Date());
  } catch (err) {
    setError(err.message || "Failed to fetch prices");
  } finally {
    setLoading(false);
  }
}, []);

  // ── Sort + Filter ─────────────────────────────────────────────────────────
  const handleSort = (key) => {
    setSortDir(prev => sortKey === key ? prev * -1 : -1);
    setSortKey(key);
  };

  const filtered = prices
    .filter(p =>
      (cat === "All" || p.category === cat) &&
      (!search || p.crop.toLowerCase().includes(search.toLowerCase()))
    )
    .sort((a, b) => {
      const av = a[sortKey], bv = b[sortKey];
      return typeof av === "string"
        ? sortDir * av.localeCompare(bv)
        : sortDir * (av - bv);
    });

  const rising   = prices.filter(p => p.change > 0).length;
  const falling  = prices.filter(p => p.change < 0).length;
  const flat     = prices.filter(p => p.change === 0).length;
  const bigMover = prices.reduce((best, p) =>
    Math.abs(p.change) > Math.abs(best?.change || 0) ? p : best, null);

  const SortArrow = ({ k }) => sortKey === k
    ? <span style={{ color: C.bg2, marginLeft: 2 }}>{sortDir === -1 ? "↓" : "↑"}</span>
    : null;

  const Th = ({ k, label }) => (
    <span
      onClick={() => handleSort(k)}
      style={{ cursor: "pointer", userSelect: "none" }}
    >
      {label}<SortArrow k={k} />
    </span>
  );

  return (
    <div style={{ padding: 22 }}>

      {/* ── Header ─────────────────────────────────────────────────────────── */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 4 }}>
        <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: 0 }}>
          📈 {TX.title}
        </h1>
        <button
          onClick={() => fetchPrices(district)}
          disabled={loading}
          style={{
            padding: "7px 16px", borderRadius: 8, fontSize: 12.5,
            border: `1.5px solid ${C.border}`, background: C.white,
            color: C.text, cursor: loading ? "not-allowed" : "pointer",
            display: "flex", alignItems: "center", gap: 6,
            opacity: loading ? 0.6 : 1,
          }}
        >
          <span style={{ fontSize: 16 }}>↻</span> Refresh
        </button>
      </div>
      <p style={{ color: C.muted, fontSize: 13, margin: "0 0 14px" }}>
        {TX.subtitle} • {prices.length} crops
        {lastUpdate && ` • Updated ${lastUpdate.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" })}`}
      </p>

      {/* ── District / Mandi Selector ─────────────────────────────────────── */}
      <Card style={{ padding: "14px 16px", marginBottom: 14 }}>
        <div style={{ display: "flex", gap: 14, flexWrap: "wrap", alignItems: "center" }}>

          {/* District dropdown */}
          <div>
            <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 5 }}>
              District
            </div>
            <select
              value={district.district}
              onChange={e => {
                const d = TN_DISTRICTS.find(x => x.district === e.target.value);
                if (d) setDistrict(d);
              }}
              style={{
                padding: "8px 12px", borderRadius: 8, border: `1.5px solid ${C.border}`,
                fontSize: 13, color: C.text, background: C.white,
                cursor: "pointer", minWidth: 200, outline: "none",
              }}
            >
              {TN_DISTRICTS.map(d => (
                <option key={d.district} value={d.district}>{d.district}</option>
              ))}
            </select>
          </div>

          {/* City / Mandi info */}
          <div>
            <div style={{ fontSize: 11, color: C.muted, fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.05em", marginBottom: 5 }}>
              City / Mandi
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <span style={{
                padding: "8px 12px", borderRadius: 8,
                background: C.pale, border: `1px solid ${C.border}`,
                fontSize: 13, color: C.bg2, fontWeight: 500,
              }}>
                🏪 {district.city}
              </span>
              <span style={{ fontSize: 12, color: C.muted }}>{district.mandi}</span>
            </div>
          </div>

          {/* Summary badges */}
          {prices.length > 0 && (
            <div style={{ marginLeft: "auto", display: "flex", gap: 8, flexWrap: "wrap" }}>
              <span style={{ padding: "6px 12px", borderRadius: 8, background: "#e8f8f0", color: C.bg2,   fontSize: 12, fontWeight: 600 }}>▲ {rising} Rising</span>
              <span style={{ padding: "6px 12px", borderRadius: 8, background: "#fdecea", color: C.red,   fontSize: 12, fontWeight: 600 }}>▼ {falling} Falling</span>
              <span style={{ padding: "6px 12px", borderRadius: 8, background: C.bg,      color: C.muted, fontSize: 12, fontWeight: 600 }}>— {flat} Unchanged</span>
              {bigMover && (
                <span style={{ padding: "6px 12px", borderRadius: 8, background: C.amberPale, color: C.amber, fontSize: 12, fontWeight: 600 }}>
                  🔥 {bigMover.crop} ({bigMover.change > 0 ? "+" : ""}{bigMover.change})
                </span>
              )}
            </div>
          )}
        </div>
      </Card>

      {/* ── Category Filters + Search ─────────────────────────────────────── */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap", alignItems: "center" }}>
        <input
          value={search}
          onChange={e => setSearch(e.target.value)}
          placeholder={TX.search}
          style={{
            padding: "8px 12px", borderRadius: 8,
            border: `1px solid ${C.border}`, fontSize: 13,
            outline: "none", width: 200, color: C.text, background: C.white,
          }}
        />
        {CATS.map(c => (
          <button key={c} onClick={() => setCat(c)} style={{
            padding: "6px 13px", borderRadius: 16, fontSize: 12.5, cursor: "pointer",
            border:     `1.5px solid ${cat === c ? C.bg2 : C.border}`,
            background: cat === c ? C.pale  : C.white,
            color:      cat === c ? C.bg2   : C.muted,
            fontWeight: cat === c ? 600     : 400,
          }}>
            {c}
          </button>
        ))}
      </div>

      {/* ── Error Banner ───────────────────────────────────────────────────── */}
      {error && (
        <div style={{
          padding: "10px 14px", borderRadius: 8,
          background: "#fdecea", border: `1px solid #f5c6c6`,
          color: C.red, fontSize: 13, marginBottom: 12,
        }}>
          ⚠️ {error} —{" "}
          <span onClick={() => fetchPrices(district)} style={{ textDecoration: "underline", cursor: "pointer" }}>
            Try again
          </span>
          <div style={{ marginTop: 5, fontSize: 11.5, color: "#b00" }}>
            Make sure <code>proxy-server.js</code> is running: <code>node proxy-server.js</code>
          </div>
        </div>
      )}

      {/* ── Price Table ────────────────────────────────────────────────────── */}
      <Card style={{ padding: 0, overflow: "hidden", marginBottom: 14 }}>

        {/* Header row */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "1.8fr 1fr 1fr 1fr 1fr 0.8fr 0.9fr",
          padding: "10px 16px", background: C.pale,
          fontSize: 11.5, fontWeight: 600, color: C.text,
          borderBottom: `1px solid ${C.border}`,
        }}>
          <Th k="crop"   label={TX.crop} />
          <Th k="modal"  label={`${TX.priceUnit} (Today)`} />
          <span style={{ color: C.muted }}>Yesterday</span>
          <Th k="change" label="Change" />
          <span>{TX.min} / {TX.max}</span>
          <span>Category</span>
          <span>{TX.trend}</span>
        </div>

        {/* Rows */}
        <div style={{ maxHeight: 520, overflowY: "auto" }}>
          {loading && <SkeletonRows />}

          {!loading && !error && filtered.length === 0 && (
            <div style={{ padding: "32px", textAlign: "center", color: C.muted, fontSize: 13 }}>
              {TX.noData}
            </div>
          )}

          {!loading && filtered.map((p, i) => {
            const prev   = p.prev > 0 ? p.prev : p.modal - p.change;
            const rowBg  = i % 2 ? C.bg : C.white;
            return (
              <div
                key={p.crop + i}
                style={{
                  display: "grid",
                  gridTemplateColumns: "1.8fr 1fr 1fr 1fr 1fr 0.8fr 0.9fr",
                  padding: "12px 16px",
                  borderBottom: `1px solid ${C.border}`,
                  background: rowBg, alignItems: "center",
                  transition: "background 0.12s",
                }}
                onMouseEnter={e => e.currentTarget.style.background = C.pale}
                onMouseLeave={e => e.currentTarget.style.background = rowBg}
              >
                {/* Crop */}
                <div>
                  <span style={{ fontSize: 13.5, fontWeight: 500, color: C.text }}>{p.crop}</span>
                  <span style={{ fontSize: 10.5, color: C.muted, marginLeft: 6 }}>{p.market}</span>
                </div>
                {/* Today modal */}
                <span style={{ fontSize: 14, fontWeight: 700, color: C.text }}>
                  ₹{p.modal.toLocaleString()}
                </span>
                {/* Yesterday */}
                <span style={{ fontSize: 12.5, color: C.muted }}>
                  {prev > 0 ? `₹${prev.toLocaleString()}` : "—"}
                </span>
                {/* Delta */}
                <DeltaPill change={p.change} prevPrice={prev} />
                {/* Min / Max */}
                <span style={{ fontSize: 12, color: C.muted }}>
                  ₹{p.min.toLocaleString()}
                  <span style={{ color: C.border, margin: "0 4px" }}>/</span>
                  ₹{p.max.toLocaleString()}
                </span>
                {/* Category */}
                <Badge color={C.muted} bg={C.bg}>
                  {(p.category || "").split(" ")[0]}
                </Badge>
                {/* Trend */}
                <TrendPill trend={p.trend} change={p.change} />
              </div>
            );
          })}
        </div>
      </Card>

      {/* ── AI Intelligence ───────────────────────────────────────────────── */}
      <Card style={{ background: C.amberPale, border: `1px solid #e0c060` }}>
        <div style={{ fontSize: 13, fontWeight: 600, color: C.amber, marginBottom: 10 }}>
          {TX.aiTitle}
          <span style={{
            marginLeft: 8, fontSize: 10.5, padding: "2px 8px", borderRadius: 99,
            background: "#fff8e0", color: C.amber, border: `1px solid #e0c060`, fontWeight: 400,
          }}>
            {district.district} district
          </span>
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {advice.map((item, i) => (
            <div key={i} style={{ fontSize: 13, color: "#5c4000", lineHeight: 1.6 }}>
              <strong style={{ color: item.color }}>{item.label}:</strong> {item.text}
            </div>
          ))}
        </div>
      </Card>

      <style>{`
        @keyframes shimmer {
          0%   { background-position:  200% 0; }
          100% { background-position: -200% 0; }
        }
      `}</style>
    </div>
  );
}

export default MarketPrices;
